def binary_search(a, target):
    lo, hi = 0, len(a) - 1
    probes = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        probes += 1
        print(f"probe {probes}: index {mid}, value {a[mid]}")
        if a[mid] == target:
            return mid, probes
        elif a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, probes

