def binary_probes(a, target):
    lo, hi, probes = 0, len(a) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        probes += 1
        if a[mid] == target:
            return probes
        elif a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return probes

def interpolation_probes(a, target):
    lo, hi, probes = 0, len(a) - 1, 0
    while lo <= hi and a[lo] <= target <= a[hi]:
        pos = lo + (target - a[lo]) * (hi - lo) // (a[hi] - a[lo])
        probes += 1
        if a[pos] == target:
            return probes
        elif a[pos] < target:
            lo = pos + 1
        else:
            hi = pos - 1
    return probes

