def height(n):
    return 0 if n is None else 1 + max(height(n.left), height(n.right))

def search_comps(n, v):
    c = 0
    while n is not None:
        c += 1
        if v == n.v:
            return c
        n = n.left if v < n.v else n.right
    return c

