adj = {1: [2], 2: [1, 3], 3: [2], 4: [5], 5: [4], 6: [], 7: []}

def component(start, seen):
    q = deque([start])
    seen.add(start)
    members = []
    while q:
        u = q.popleft()
        members.append(u)
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                q.append(v)
    return members

