def naive_max_min(a):
    comps = 0
    mx = mn = a[0]
    for x in a[1:]:
        comps += 1
        if x > mx:
            mx = x
        comps += 1
        if x < mn:
            mn = x
    return mx, mn, comps

def pairwise_max_min(a):
    comps = 0
    if a[0] < a[1]:
        mn, mx = a[0], a[1]
    else:
        mn, mx = a[1], a[0]
    comps += 1
    for i in range(2, len(a) - 1, 2):
        x, y = a[i], a[i + 1]
        comps += 1
        if x > y:
            x, y = y, x   # now x <= y
        comps += 1
        if x < mn:
            mn = x
        comps += 1
        if y > mx:
            mx = y
    return mx, mn, comps

print("naive:", naive_max_min(data))
print("pairwise:", pairwise_max_min(data))

def dedupe(items):
    seen = set()
    out = []
    for x in items:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

