def quickselect(a, k):  # k is 1-based
    lo, hi = 0, len(a) - 1
    while True:
        pivot = a[hi]
        i = lo
        for j in range(lo, hi):
            if a[j] < pivot:
                a[i], a[j] = a[j], a[i]
                i += 1
        a[i], a[hi] = a[hi], a[i]
        if i == k - 1:
            return a[i]
        elif i < k - 1:
            lo = i + 1
        else:
            hi = i - 1

